using System;using System.Collections.Generic;using System.Linq;using KingmakerMountedCombat.Diagnostics;
namespace KingmakerMountedCombat.Tests {
internal static class CumulativeProtocolTests {
 private const string Id="11111111-1111-4111-8111-111111111111",NewId="22222222-1111-4111-8111-111111111111",Area="0123456789abcdef0123456789abcdef",NewArea="fedcba9876543210fedcba9876543210";
 private static int Main(){var tests=new TestRunner();
 tests.Run("closed Manual-derived acquisition request",()=>{var r=Request();TestRunner.Equal(0,r.Validate().Count,string.Join("; ",r.Validate()));TestRunner.Equal("Manual",r.ExpectedNativeLoadType,"Wrong native input category.");});
 tests.Run("owner-seed one-owner Manual 305 to 306 is a closed distinct route",()=>{var r=Request();r.CumulativeAcquisition.SourceMode=Chunk7CumulativeAcquisitionSelection.OwnerSeedSourceMode;r.CumulativeAcquisition.NativeWriteLeaf=Chunk7CumulativeAcquisitionSelection.OwnerSeedManualOutputLeaf;r.PersistenceLoad.FileName=Chunk7CumulativeAcquisitionSelection.OwnerSeedSourceLeaf;TestRunner.Equal(0,r.Validate().Count,string.Join("; ",r.Validate()));TestRunner.True(r.CumulativeAcquisition.IsSelectedManualLeaf(r.PersistenceLoad.FileName),"Owner-seed source refused.");TestRunner.True(!r.CumulativeAcquisition.IsSelectedManualLeaf(Chunk7CumulativeAcquisitionSelection.LegacySourceLeaf),"Legacy source crossed modes.");r.CumulativeAcquisition.AssistedColdRunId="foreign";TestRunner.True(r.Validate().Count>0,"Assisted pins crossed into owner-seed route.");});
 tests.Run("owner-seed source and output remain paired in native authority",()=>{BootstrapVirtualFile.OwnerSeed=true;try{var f=new Fixture();f.Source.FileName=Chunk7CumulativeAcquisitionSelection.OwnerSeedSourceLeaf;var e=f.Entries();e[0].FileName=f.Source.FileName;e[1].FileName=Chunk7CumulativeAcquisitionSelection.OwnerSeedManualOutputLeaf;var a=f.Scope(e);TestRunner.True(a.MatchesCumulativeAcquisitionPlan(f.Source,e[1].FileName,e[1].InternalName,true),"Owner-seed plan refused.");TestRunner.True(!a.MatchesCumulativeAcquisitionPlan(f.Source,Chunk7CumulativeAcquisitionSelection.LegacyManualOutputLeaf,e[1].InternalName,true),"Owner-seed source borrowed legacy output.");f.Source.FileName=Chunk7CumulativeAcquisitionSelection.LegacySourceLeaf;TestRunner.True(!a.MatchesCumulativeAcquisitionPlan(f.Source,e[1].FileName,e[1].InternalName,true),"Legacy source borrowed owner-seed output.");}finally{BootstrapVirtualFile.OwnerSeed=false;}});
 foreach(var name in new[]{"missing selection","old bridge","foreign scenario","alias case","base false","second load","second write","no write","same source run","bad source hash","missing input","anchor campaign","anchor archive","wrong leaf","source hash mismatch","schema1","persistence case","route","alternate","bootstrap permission","missing readiness"})tests.Run("Manual-derived acquisition refuses "+name,()=>{var r=Request();switch(name){case "missing selection":r.CumulativeAcquisition=null;break;case "old bridge":r.BootstrapInventory=new Chunk7BootstrapInventorySelection();break;case "foreign scenario":r.Scenario="fixture-intake";break;case "alias case":r.CumulativeAcquisition.Case="arrange";break;case "base false":r.CumulativeAcquisition.BaseGameOnly=false;break;case "second load":r.CumulativeAcquisition.ExpectedNativeLoadCount=2;break;case "second write":r.CumulativeAcquisition.ExpectedNativeWriteCount=2;break;case "no write":r.CumulativeAcquisition.ExpectedNativeWriteCount=0;break;case "same source run":r.CumulativeAcquisition.SourceRunId=r.RunId;break;case "bad source hash":r.CumulativeAcquisition.SourceArtifactSha256="bad";break;case "missing input":r.PersistenceLoad=null;break;case "anchor campaign":r.PersistenceLoad.GameId=Id;break;case "anchor archive":r.PersistenceLoad.Sha256=r.Fixture.Working.Sha256;r.CumulativeAcquisition.SourceArchiveSha256=r.PersistenceLoad.Sha256;break;case "wrong leaf":r.PersistenceLoad.FileName="Auto_2.zks";break;case "source hash mismatch":r.PersistenceLoad.Sha256=new string('e',64);break;case "schema1":r.SchemaVersion=1;break;case "persistence case":r.PersistenceCase="multi-exploration-manual";break;case "route":r.PersistenceAreaTarget=new RuntimeAreaTransitionTarget();break;case "alternate":r.PersistenceAlternate=r.PersistenceLoad;break;case "bootstrap permission":r.NativeBootstrap=new Chunk7NativeBootstrapSelection();break;case "missing readiness":r.CumulativeAcquisition.Readiness=null;break;}TestRunner.True(r.Validate().Count>0,"Foreign source or authority admitted.");});
 tests.Run("historical Working request remains exact",()=>{var r=Request();r.Scenario="fixture-intake";r.CumulativeAcquisition=null;r.PersistenceLoad=null;TestRunner.Equal(0,r.Validate().Count,"Old admission changed.");});
 tests.Run("closed result rows",()=>{foreach(var row in new[]{"C7-cumulative-source","C7-cumulative-native-load","C7-cumulative-eligibility","C7-cumulative-native-choices","C7-cumulative-native-field","C7-cumulative-native-manual-save","C7-cumulative-cleanup","C7-cumulative-runtime","C7-cumulative-interrupted"})TestRunner.True(RuntimeSubscenarioResult.IsMissionScenario(row),"Row missing.");TestRunner.True(!RuntimeSubscenarioResult.IsMissionScenario("C7-cumulative-native-autosave"),"Obsolete Auto row accepted.");TestRunner.True(!RuntimeSubscenarioResult.IsMissionScenario("C7-cumulative-grant"),"Open row accepted.");});
 tests.Run("one immutable Manual load and one fresh Manual worker lease",()=>{BootstrapVirtualFile.OutputExists=false;var f=new Fixture();var a=f.Scope();TestRunner.True(a.MatchesCumulativeAcquisitionPlan(f.Source,f.Write.FileName,f.Write.InternalName,true),"Exact plan refused.");for(int i=0;i<3;i++)TestRunner.True(a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Read-only load eligibility refused.");TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"Validation spent admission.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"First load refused.");TestRunner.True(a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Second disposal authorized.");TestRunner.True(a.ValidateArchiveIdentity(f.Load,f.Root)==null,"Completed input inspection refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Load,f.Root)!=null,"Input became writable.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write,f.Root)==null,"Manual write refused.");TestRunner.True(!a.MatchesCumulativeAcquisitionPlan(f.Source,f.Write.FileName,f.Write.InternalName,true),"Write admission remains unspent.");using(var lease=a.BeginWrite(f.Write,f.Root)){TestRunner.True(a.MatchesCumulativeAcquisitionPlan(f.Source,f.Write.FileName,f.Write.InternalName,false),"Owned active worker lost scope.");BootstrapVirtualFile.OutputExists=true;lease.Complete();}TestRunner.True(a.MatchesCumulativeAcquisitionPlan(f.Source,f.Write.FileName,f.Write.InternalName,false),"Completed exact two-entry scope lost.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write,f.Root)!=null,"Second write admitted.");TestRunner.True(a.ValidateArchiveIdentity(f.Load,f.Root)==null,"Write changed input admission.");TestRunner.Equal(1,a.AdmittedNativeWriteRequests,"Wrong write total.");BootstrapVirtualFile.OutputExists=false;});
 foreach(var name in new[]{"load2","no load cap","no write cap","write2","writable source","no output","third entry","wrong source hash","wrong source game","wrong output name","wrong output area","wrong output type","transition","foreign","bootstrap","wrong leaf"})tests.Run("two-entry derived authority refuses "+name,()=>{BootstrapVirtualFile.OutputExists=false;var f=new Fixture();var e=f.Entries();int? loads=1,writes=1;switch(name){case "load2":loads=2;break;case "no load cap":loads=null;break;case "no write cap":writes=null;break;case "write2":writes=2;break;case "writable source":e[0].Writable=true;break;case "no output":e=e.Take(1).ToArray();break;case "third entry":e=e.Concat(new[]{new PersistenceSaveEntry{FileName="Manual_2_other.zks",InternalName="other",SaveType="Manual",Area=NewArea,Writable=true}}).ToArray();break;case "wrong source hash":f.Source.Sha256=new string('e',64);break;case "wrong source game":f.Source.GameId=Id;break;case "wrong output name":e[1].InternalName="other";break;case "wrong output area":e[1].Area=Area;break;case "wrong output type":e[1].SaveType="Quick";break;case "transition":e[1].AdmissionArea=Area;break;case "foreign":e[1].ForeignGameId=Id;e[1].ForeignGameName="Foreign";break;case "bootstrap":e[1].Campaign="B";e[1].AdmitsBeforeArea=true;break;case "wrong leaf":e[1].FileName="Manual_2_KMC_C7_ACQUIRED_FIELD.zks";break;}bool refused;try{refused=!f.Scope(e,loads,writes).MatchesCumulativeAcquisitionPlan(f.Source,f.Write.FileName,f.Write.InternalName,true);}catch(ArgumentException){refused=true;}TestRunner.True(refused,"Foreign plan admitted.");});
 tests.Run("preexisting output cannot be adopted",()=>{BootstrapVirtualFile.OutputExists=true;var f=new Fixture();bool refused=false;try{var a=f.Scope();refused=a.Validate(RuntimeSaveOperation.Write,f.Write,f.Root)!=null;}catch(System.IO.IOException){refused=true;}finally{BootstrapVirtualFile.OutputExists=false;}TestRunner.True(refused,"Existing archive adopted.");});
 tests.Run("cumulative source cannot borrow historical seed authority",()=>{var f=new Fixture();TestRunner.True(!f.Scope().MatchesManualDerivedPlan(f.Source,f.Write.FileName,f.Write.InternalName,true),"Historical seed authority widened.");});
 foreach(var item in new[]{"missing prior","same prior","selected prior","prior pet in characters","invalid Manual number","other valid Manual number","noncanonical Manual number","old seed source"})tests.Run("cumulative refuses "+item,()=>{var r=Request();switch(item){case "missing prior":r.CumulativeAcquisition.PriorOwnerId=null;break;case "same prior":r.CumulativeAcquisition.PriorPetId=r.CumulativeAcquisition.PriorOwnerId;break;case "selected prior":r.CumulativeAcquisition.ExistingActorId=r.CumulativeAcquisition.PriorOwnerId;break;case "prior pet in characters":r.CumulativeAcquisition.PriorPetId=r.CumulativeAcquisition.ExistingActorId;break;case "invalid Manual number":r.PersistenceLoad.FileName="Manual_2147483648_KMC_C7_ACQUIRED_FIELD.zks";break;case "other valid Manual number":r.PersistenceLoad.FileName="Manual_305_KMC_C7_ACQUIRED_FIELD.zks";break;case "noncanonical Manual number":r.PersistenceLoad.FileName="Manual_07_KMC_C7_ACQUIRED_FIELD.zks";break;case "old seed source":r.PersistenceLoad.FileName="Manual_1_KMC_C7_NATIVE_SEED.zks";r.PersistenceLoad.InternalName="KMC_C7_NATIVE_SEED";break;}TestRunner.True(r.Validate().Count>0,"Invalid cumulative graph/input accepted.");});
 tests.Run("closed two-owner Manual selection",()=>{var s=Two();TestRunner.Equal(0,s.Validate(Chunk7AcquiredManualSelection.Scenario,"current").Count,"Exact two-owner source refused.");TestRunner.True(s.ShouldSerializePriorOwnerId()&&s.ShouldSerializePriorPetId(),"Two-owner pins not projected.");});
 foreach(var item in new[]{"same pair","missing prior","foreign case","one-owner borrowing"})tests.Run("two-owner Manual refuses "+item,()=>{var s=Two();switch(item){case "same pair":s.PriorOwnerId=s.ActorId;break;case "missing prior":s.PriorPetId=null;break;case "foreign case":s.Case="preserve-three-acquired-field";break;case "one-owner borrowing":s.Case=Chunk7AcquiredManualSelection.CaseName;break;}TestRunner.True(s.Validate(Chunk7AcquiredManualSelection.Scenario,"current").Count>0,"Invalid two-owner source admitted.");});
 tests.Run("original one-owner projection stays exact",()=>{var s=Two();s.Case=Chunk7AcquiredManualSelection.CaseName;s.PriorOwnerId=null;s.PriorPetId=null;TestRunner.Equal(0,s.Validate(Chunk7AcquiredManualSelection.Scenario,"current").Count,"Original source refused.");TestRunner.True(!s.ShouldSerializePriorOwnerId()&&!s.ShouldSerializePriorPetId(),"Old request gained extra pins.");});
 return tests.Complete();}
