internal static class BootstrapVirtualDirectory {internal static IEnumerable<string> EnumerateFileSystemEntries(string path)=>new[]{path+@"\"+(BootstrapVirtualFile.OwnerSeed?Chunk7CumulativeAcquisitionSelection.OwnerSeedSourceLeaf:Chunk7CumulativeAcquisitionSelection.LegacySourceLeaf)};internal static bool Exists(string path)=>!path.EndsWith(".zks",StringComparison.Ordinal);}
internal static class BootstrapVirtualFile {internal static bool OutputExists,OwnerSeed;internal static bool Exists(string path)=>path.EndsWith(OwnerSeed?Chunk7CumulativeAcquisitionSelection.OwnerSeedSourceLeaf:Chunk7CumulativeAcquisitionSelection.LegacySourceLeaf,StringComparison.Ordinal)||(OutputExists&&path.EndsWith(OwnerSeed?Chunk7CumulativeAcquisitionSelection.OwnerSeedManualOutputLeaf:Chunk7CumulativeAcquisitionSelection.LegacyManualOutputLeaf,StringComparison.Ordinal));internal static void Delete(string path){throw new InvalidOperationException("Unexpected filesystem mutation.");}}
internal static class BootstrapVirtualStorage {internal static void RequireDirectory(string path){if(string.IsNullOrEmpty(path))throw new InvalidOperationException();}internal static string Hash(string path)=>new string(path.EndsWith(BootstrapVirtualFile.OwnerSeed?Chunk7CumulativeAcquisitionSelection.OwnerSeedSourceLeaf:Chunk7CumulativeAcquisitionSelection.LegacySourceLeaf,StringComparison.Ordinal)?'d':'f',64);}
